macro_rules! deps {
    () => {
        PlaceConflictBias!();
        Overlap!();
    };
}

macro_rules! place_projection_conflict {
    () => {
        deps!();
        fn place_projection_conflict < 'tcx > (tcx : TyCtxt < 'tcx > , body : & Body < 'tcx > , pi1 : PlaceRef < 'tcx > , pi1_elem : PlaceElem < 'tcx > , pi2_elem : PlaceElem < 'tcx > , bias : PlaceConflictBias ,) -> Overlap { match (pi1_elem , pi2_elem) { (ProjectionElem :: Deref , ProjectionElem :: Deref) => { debug ! ("place_element_conflict: DISJOINT-OR-EQ-DEREF") ; Overlap :: EqualOrDisjoint } (ProjectionElem :: OpaqueCast (_) , ProjectionElem :: OpaqueCast (_)) => { debug ! ("place_element_conflict: DISJOINT-OR-EQ-OPAQUE") ; Overlap :: EqualOrDisjoint } (ProjectionElem :: Field (f1 , _) , ProjectionElem :: Field (f2 , _)) => { if f1 == f2 { debug ! ("place_element_conflict: DISJOINT-OR-EQ-FIELD") ; Overlap :: EqualOrDisjoint } else { let ty = pi1 . ty (body , tcx) . ty ; if ty . is_union () { debug ! ("place_element_conflict: STUCK-UNION") ; Overlap :: Arbitrary } else { debug ! ("place_element_conflict: DISJOINT-FIELD") ; Overlap :: Disjoint } } } (ProjectionElem :: Downcast (_ , v1) , ProjectionElem :: Downcast (_ , v2)) => { if v1 == v2 { debug ! ("place_element_conflict: DISJOINT-OR-EQ-FIELD") ; Overlap :: EqualOrDisjoint } else { debug ! ("place_element_conflict: DISJOINT-FIELD") ; Overlap :: Disjoint } } (ProjectionElem :: Index (..) , ProjectionElem :: Index (..) | ProjectionElem :: ConstantIndex { .. } | ProjectionElem :: Subslice { .. } ,) | (ProjectionElem :: ConstantIndex { .. } | ProjectionElem :: Subslice { .. } , ProjectionElem :: Index (..) ,) => { match bias { PlaceConflictBias :: Overlap => { debug ! ("place_element_conflict: DISJOINT-OR-EQ-ARRAY-INDEX") ; Overlap :: EqualOrDisjoint } PlaceConflictBias :: NoOverlap => { debug ! ("place_element_conflict: DISJOINT-ARRAY-INDEX") ; Overlap :: Disjoint } } } (ProjectionElem :: ConstantIndex { offset : o1 , min_length : _ , from_end : false } , ProjectionElem :: ConstantIndex { offset : o2 , min_length : _ , from_end : false } ,) | (ProjectionElem :: ConstantIndex { offset : o1 , min_length : _ , from_end : true } , ProjectionElem :: ConstantIndex { offset : o2 , min_length : _ , from_end : true } ,) => { if o1 == o2 { debug ! ("place_element_conflict: DISJOINT-OR-EQ-ARRAY-CONSTANT-INDEX") ; Overlap :: EqualOrDisjoint } else { debug ! ("place_element_conflict: DISJOINT-ARRAY-CONSTANT-INDEX") ; Overlap :: Disjoint } } (ProjectionElem :: ConstantIndex { offset : offset_from_begin , min_length : min_length1 , from_end : false , } , ProjectionElem :: ConstantIndex { offset : offset_from_end , min_length : min_length2 , from_end : true , } ,) | (ProjectionElem :: ConstantIndex { offset : offset_from_end , min_length : min_length1 , from_end : true , } , ProjectionElem :: ConstantIndex { offset : offset_from_begin , min_length : min_length2 , from_end : false , } ,) => { let min_length = max (min_length1 , min_length2) ; if offset_from_begin >= min_length - offset_from_end { debug ! ("place_element_conflict: DISJOINT-OR-EQ-ARRAY-CONSTANT-INDEX-FE") ; Overlap :: EqualOrDisjoint } else { debug ! ("place_element_conflict: DISJOINT-ARRAY-CONSTANT-INDEX-FE") ; Overlap :: Disjoint } } (ProjectionElem :: ConstantIndex { offset , min_length : _ , from_end : false } , ProjectionElem :: Subslice { from , to , from_end : false } ,) | (ProjectionElem :: Subslice { from , to , from_end : false } , ProjectionElem :: ConstantIndex { offset , min_length : _ , from_end : false } ,) => { if (from .. to) . contains (& offset) { debug ! ("place_element_conflict: DISJOINT-OR-EQ-ARRAY-CONSTANT-INDEX-SUBSLICE") ; Overlap :: EqualOrDisjoint } else { debug ! ("place_element_conflict: DISJOINT-ARRAY-CONSTANT-INDEX-SUBSLICE") ; Overlap :: Disjoint } } (ProjectionElem :: ConstantIndex { offset , min_length : _ , from_end : false } , ProjectionElem :: Subslice { from , .. } ,) | (ProjectionElem :: Subslice { from , .. } , ProjectionElem :: ConstantIndex { offset , min_length : _ , from_end : false } ,) => { if offset >= from { debug ! ("place_element_conflict: DISJOINT-OR-EQ-SLICE-CONSTANT-INDEX-SUBSLICE") ; Overlap :: EqualOrDisjoint } else { debug ! ("place_element_conflict: DISJOINT-SLICE-CONSTANT-INDEX-SUBSLICE") ; Overlap :: Disjoint } } (ProjectionElem :: ConstantIndex { offset , min_length : _ , from_end : true } , ProjectionElem :: Subslice { to , from_end : true , .. } ,) | (ProjectionElem :: Subslice { to , from_end : true , .. } , ProjectionElem :: ConstantIndex { offset , min_length : _ , from_end : true } ,) => { if offset > to { debug ! ("place_element_conflict: \
                       DISJOINT-OR-EQ-SLICE-CONSTANT-INDEX-SUBSLICE-FE") ; Overlap :: EqualOrDisjoint } else { debug ! ("place_element_conflict: DISJOINT-SLICE-CONSTANT-INDEX-SUBSLICE-FE") ; Overlap :: Disjoint } } (ProjectionElem :: Subslice { from : f1 , to : t1 , from_end : false } , ProjectionElem :: Subslice { from : f2 , to : t2 , from_end : false } ,) => { if f2 >= t1 || f1 >= t2 { debug ! ("place_element_conflict: DISJOINT-ARRAY-SUBSLICES") ; Overlap :: Disjoint } else { debug ! ("place_element_conflict: DISJOINT-OR-EQ-ARRAY-SUBSLICES") ; Overlap :: EqualOrDisjoint } } (ProjectionElem :: Subslice { .. } , ProjectionElem :: Subslice { .. }) => { debug ! ("place_element_conflict: DISJOINT-OR-EQ-SLICE-SUBSLICES") ; Overlap :: EqualOrDisjoint } (ProjectionElem :: Deref | ProjectionElem :: Field (..) | ProjectionElem :: Index (..) | ProjectionElem :: ConstantIndex { .. } | ProjectionElem :: Subtype (_) | ProjectionElem :: OpaqueCast { .. } | ProjectionElem :: Subslice { .. } | ProjectionElem :: Downcast (..) , _ ,) => bug ! ("mismatched projections in place_element_conflict: {:?} and {:?}" , pi1_elem , pi2_elem) , (ProjectionElem :: UnwrapUnsafeBinder (_) , _) => { todo ! () } } }
    };
}

place_projection_conflict!()